function trackCard(t){const done=trackDone(t),qp=t.questions.length,cp=t.incidents.length;return '<article class="track-card '+(done?"done":"")+'"><div class="track-top"><span class="track-no">TRACK '+t.num+'</span><span class="level">'+t.level+'</span></div><h3>'+esc(t.title)+'</h3><p>'+esc(t.short)+'</p><div class="chip-row">'+t.tools.split(" · ").slice(0,4).map(x=>'<span class="chip">'+esc(x)+'</span>').join("")+'</div><div class="track-bottom"><small>'+qp+' questions · '+cp+' incidents</small><button data-open-track="'+t.id+'">'+(done?"REVIEW TRACK ↗":"OPEN TRACK →")+'</button></div></article>';}
function stats(){return '<div class="grid stats-grid"><div class="stat-card"><div class="label">ROADMAP COMPLETION</div><div class="value accent">'+progressPercent()+'%</div><small>'+state.doneTracks.length+' / '+CURRICULUM.length+' learning tracks completed</small>'+progressBar(progressPercent())+'</div><div class="stat-card"><div class="label">QUESTIONS MASTERED</div><div class="value">'+completedQuestions()+'</div><small>of '+allQuestions()+' track-specific questions</small></div><div class="stat-card"><div class="label">INCIDENT REVIEWS</div><div class="value">'+completedCases()+'</div><small>of '+allCases()+' production scenarios scored</small></div><div class="stat-card"><div class="label">FOCUSED STUDY TIME</div><div class="value">'+Math.floor(state.totalSeconds/3600)+'<small>h</small> '+Math.floor(state.totalSeconds%3600/60)+'<small>m</small></div><small>Timer only counts while running and page is visible</small></div></div>';}
function renderOverview(){
 const recent=state.ratings.slice(-3).reverse();
 root.innerHTML=stats()+
 sectionHead("YOUR NEXT MILESTONE","Build your engineering foundation","Move through the tracks in order. Learn the concept, attempt the questions, investigate the incidents and complete the lab.",'<button class="btn secondary" data-go="roadmap">Full roadmap ↗</button>')+
 '<div class="grid split-grid"><section class="panel"><h3>Learning journey</h3><p class="panel-sub">17 connected tracks · Foundation to production</p>'+CURRICULUM.slice(0,7).map(t=>'<div class="progress-row"><span>'+t.num+' · '+esc(t.title)+'</span><span>'+(trackDone(t)?"COMPLETE":"UP NEXT")+'</span></div>'+progressBar(trackDone(t)?100:0)).join("")+'<div style="margin-top:14px"><button class="btn secondary" data-go="roadmap">View all tracks →</button></div></section><section class="panel"><h3>Practice workspace</h3><p class="panel-sub">Apply ideas, not just memorize terms.</p><div class="quick-actions"><button class="quick-action" data-go="terminal"><b>$_ Terminal</b><small>Practice safe command workflows</small></button><button class="quick-action" data-go="code"><b>⌁ Code repair</b><small>Fix broken engineering files</small></button><button class="quick-action" data-go="incidents"><b>⚠ Incident arena</b><small>Investigate production scenarios</small></button><button class="quick-action" data-go="projects"><b>◫ Projects</b><small>Build progressive portfolio work</small></button></div></section></div>'+
 sectionHead("START HERE","Core roadmap tracks","Open a track to learn, answer its questions and run its practical lab.")+
 '<div class="grid roadmap-grid">'+CURRICULUM.slice(0,6).map(trackCard).join("")+'</div>'+
 sectionHead("YOUR PERFORMANCE","Recent approach reviews","Scores are a coaching signal based on the reasoning you submit, not a formal certification.")+
 (recent.length?'<div class="grid senior-grid">'+recent.map(r=>'<article class="senior-card"><span class="spark">✦</span><h3>'+esc(r.label)+'</h3><p>'+esc(r.summary)+'</p><div class="rating">APPROACH SCORE · '+r.score+'/100</div></article>').join("")+'</div>':'<div class="empty">No scored practice yet. Try the Incident Simulator and explain your investigation approach.</div>');
}
