 const levels=["ALL","FOUNDATION","FOUNDATION → INTERMEDIATE","INTERMEDIATE","ADVANCED","EMERGING → PRODUCTION","PRODUCTION"];
 root.innerHTML=sectionHead("ROADMAP MAP","From first command to production ownership","Complete each track's concepts, 10 questions, 5 incident scenarios and practical lab. Use the filter to focus a stage.",'<div class="roadmap-toolbar">'+levels.map(l=>'<button class="filter-btn '+(roadmapFilter===l?"active":"")+'" data-filter="'+esc(l)+'">'+(l==="ALL"?"ALL STAGES":l)+'</button>').join("")+'</div>')+
 '<div class="grid roadmap-grid">'+CURRICULUM.filter(t=>roadmapFilter==="ALL"||t.level===roadmapFilter).map(trackCard).join("")+'</div>'+
 '<div class="notice">Suggested progression: foundation → intermediate → advanced → production. Some tools can be learned in parallel, but keep Linux, Git, networking and scripting as your base.</div>';
