function renderCode(){const challenges=[
{id:"docker",name:"Harden a Docker image",tag:"CONTAINERS",desc:"The Dockerfile runs as root and copies the entire build context. Make the runtime smaller and non-root.",starter:"FROM node:latest\nWORKDIR /app\nCOPY . .\nRUN npm install\nEXPOSE 3000\nCMD [\"npm\",\"start\"]",hint:"Use a pinned minimal base, multi-stage build where appropriate, .dockerignore, production-only dependencies and a non-root runtime user.",checks:[["USER node","Run as non-root"],["npm ci","Use reproducible lockfile install"],["COPY package*.json","Copy dependency manifest before install"],["--only=production","Install production dependencies or equivalent"],["EXPOSE 3000","Document service port"]] },
{id:"actions",name:"Repair a GitHub Actions workflow",tag:"CI/CD",desc:"The workflow has broad permissions and no build/test gate. Add a minimal permission set and test the Java app.",starter:"name: build\non: [push]\npermissions: write-all\njobs:\n  build:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@main\n      - run: echo Build started",hint:"Use contents: read, pin a stable checkout version, set up the required JDK, and run Maven clean verify.",checks:[["contents: read","Use read-only repository permission"],["actions/checkout@v4","Use a versioned checkout action"],["setup-java","Set up the JDK"],["mvn","Run Maven build and tests"],["clean verify","Run clean verification lifecycle"]] },
{id:"terraform",name:"Secure a Terraform storage resource",tag:"IaC + SECURITY",desc:"The current config allows public access and has no encryption or version recovery. Add secure defaults.",starter:"resource \"aws_s3_bucket\" \"data\" {\n  bucket = \"my-app-data-example\"\n}\n\nresource \"aws_s3_bucket_public_access_block\" \"data\" {\n  bucket = aws_s3_bucket.data.id\n  block_public_acls       = false\n  block_public_policy     = false\n  ignore_public_acls      = false\n  restrict_public_buckets = false\n}",hint:"Set all public access block options true. Add server-side encryption and versioning resources/configuration. Validate the plan; this challenge does not create a bucket.",checks:[["block_public_acls       = true","Block public ACLs"],["block_public_policy     = true","Block public policies"],["ignore_public_acls      = true","Ignore public ACLs"],["restrict_public_buckets = true","Restrict public bucket policy"],["aws_s3_bucket_versioning","Enable version recovery"]] },
{id:"k8s",name:"Make a Kubernetes workload safer",tag:"KUBERNETES",desc:"This Pod has no resource boundaries, probe or non-root security context. Improve the manifest.",starter:"apiVersion: v1\nkind: Pod\nmetadata:\n  name: employee-api\nspec:\n  containers:\n    - name: api\n      image: employee-api:latest\n      ports:\n        - containerPort: 8080",hint:"Add startup/readiness/liveness probes with correct paths and timings, resources requests/limits, and a non-root security context.",checks:[["readinessProbe","Gate traffic on readiness"],["livenessProbe","Detect stuck process"],["resources:","Set resource controls"],["requests:","Set scheduler requests"],["runAsNonRoot: true","Run without root"]] },
{id:"bash",name:"Stop an unsafe cleanup script",tag:"AUTOMATION",desc:"The script accepts any path and deletes files immediately. Make it safer and support dry-run.",starter:"#!/usr/bin/env bash\nTARGET=$1\nfind $TARGET -type f -mtime +14 -delete\necho cleanup complete",hint:"Add strict mode, validate required argument and directory, quote variables, constrain allowed paths and print candidates before delete.",checks:[["set -euo pipefail","Enable deliberate strict handling"],["${1:?","Validate argument"],["-d","Validate target directory"],["\"$TARGET\"","Quote target variable"],["-print","Preview candidates before destructive action"]] },
{id:"security",name:"Add supply-chain checks",tag:"DEVSECOPS",desc:"The build publishes an image without scanning or recording a digest. Add both controls.",starter:"docker build -t employee-api:latest .\ndocker push registry.example/employee-api:latest",hint:"Build a versioned image, scan the image, capture its digest and make publishing conditional on policy success.",checks:[["trivy image","Scan the final image"],["sha256","Record a digest or use registry digest"],["VERSION","Use a release version rather than only latest"],["if","Gate publish on scan status"]] }
];const chosen=window.activeChallenge||challenges[0].id;const ch=challenges.find(x=>x.id===chosen)||challenges[0];root.innerHTML=sectionHead("CODE REPAIR ARENA","Find the defect. Fix the file. Prove the fix.","Write code in the editor. The checker validates important engineering controls; it is not a full compiler or security scanner.")+
 '<div class="roadmap-toolbar">'+challenges.map(x=>'<button class="filter-btn '+(x.id===ch.id?"active":"")+'" data-challenge="'+x.id+'">'+esc(x.tag)+'</button>').join("")+'</div><div class="view-head"><div><div class="section-kicker">'+esc(ch.tag)+'</div><h2>'+esc(ch.name)+'</h2><p>'+esc(ch.desc)+'</p></div><span class="level">CHALLENGE</span></div>'+
 '<div class="challenge-layout"><section class="panel"><h3>Broken starter file</h3><p class="panel-sub">Edit the code below to satisfy the acceptance checks.</p><textarea id="codeEditor" class="code-editor" spellcheck="false">'+esc(ch.starter)+'</textarea><div class="editor-toolbar"><button class="small-btn" data-code-hint>Show hint</button><button class="btn primary" data-check-code="'+ch.id+'">Run checks →</button></div><div class="hint-panel" id="codeHint"><b>ENGINEERING HINT</b><p>'+esc(ch.hint)+'</p></div><div id="codeResult" class="answer-panel"></div></section><section class="panel"><h3>Acceptance criteria</h3><p class="panel-sub">Each criterion is a small engineering control to verify.</p><div id="criteriaList">'+ch.checks.map((x,i)=>'<div class="progress-row"><span>'+esc(x[1])+'</span><span>NOT CHECKED</span></div>'+progressBar(0)).join("")+'</div><div class="notice">This arena uses simple content checks. Passing does not replace Docker build, terraform validate, YAML lint, tests or a security scan in a real environment.</div></section></div>';
}
function checkCode(id){const map={docker:[["USER node","run non-root"],["npm ci","reproducible install"],["COPY package*.json","manifest-first copy"],["--only=production","production dependencies"],["EXPOSE 3000","port documented"]],actions:[["contents: read","minimal permissions"],["actions/checkout@v4","versioned checkout"],["setup-java","JDK setup"],["mvn","Maven build"],["clean verify","tests and verification"]],terraform:[["block_public_acls       = true","block public ACLs"],["block_public_policy     = true","block public policy"],["ignore_public_acls      = true","ignore public ACLs"],["restrict_public_buckets = true","restrict public buckets"],["aws_s3_bucket_versioning","versioning"]],k8s:[["readinessProbe","readiness"],["livenessProbe","liveness"],["resources:","resources"],["requests:","requests"],["runAsNonRoot: true","non-root"]],bash:[["set -euo pipefail","strict error handling"],["${1:?","validate argument"],["-d","directory validation"],["\"$TARGET\"","quote variable"],["-print","dry run"]],security:[["trivy image","image scanning"],["sha256","digest"],["VERSION","immutable version"],["if","scan gate"]]};const req=map[id],value=$("#codeEditor").value;const failed=req.filter(x=>!value.includes(x[0]));const passed=req.length-failed.length;const score=Math.round(passed/req.length*100);$("#criteriaList").innerHTML=req.map(x=>'<div class="progress-row"><span>'+esc(x[1])+'</span><span>'+(value.includes(x[0])?"PASS":"MISSING")+'</span></div>'+progressBar(value.includes(x[0])?100:0)).join("");const res=$("#codeResult");res.classList.add("show");res.innerHTML='<b>CHECK RESULT · '+score+'/100</b><p>'+passed+' of '+req.length+' acceptance checks passed.</p><p>'+(failed.length?"Still missing: "+failed.map(x=>x[1]).join(", "):"All simple checks passed. Validate with the real toolchain before using this in a project.")+'</p>';if(score===100){state.projectChecks["code:"+id]=true;save();toast("Challenge checks passed. Great work.");}else toast("Review the missing criteria and iterate.");}
